const H = { apikey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJyZGdnaHd4dWluY2ZlbmdranlkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODE2Mzg2NzYsImV4cCI6MjA5NzIxNDY3Nn0.CmiMS40IN__uzW8s2gt29oBfGs9Waj1Xn1voZXjpyPY' };
H.Authorization = 'Bearer ' + H.apikey;
const base = 'https://rrdgghwxuincfengkjyd.supabase.co/rest/v1/';
const problems = [];
try {
  const rec = await this.helpers.httpRequest({ url: base + 'ai_reconciliation?select=*', headers: H, json: true });
  const r = rec && rec[0];
  if (!r) problems.push('reconciliation view returned no rows');
  else if (!r.reconciled) problems.push('*Reconciliation FAILED* — headline $' + r.headline_commission + ' vs months $' + r.month_sum_commission + ' vs bots $' + r.bot_sum_commission + ' (overlap $' + r.bot_overlap_amount + ')');
} catch (err) { problems.push('could not read ai_reconciliation: ' + err.message); }
try {
  const k = await this.helpers.httpRequest({ url: base + 'ai_kpi_summary?select=as_of&limit=1', headers: H, json: true });
  const asOf = k && k[0] && k[0].as_of;
  const today = new Date().toISOString().slice(0, 10);
  if (!asOf) problems.push('kpi_summary is empty');
  else if (asOf < today) problems.push('*Mart is STALE* — last refresh ' + asOf + ' (commission ETL may have silently not run)');
} catch (err) { problems.push('could not read ai_kpi_summary: ' + err.message); }
if (!problems.length) return [];
return [{ json: { text: ':warning: *AI Impact daily health check*\n• ' + problems.join('\n• ') } }];
